// Builds ../mailbox-group-access.yml from the scripts in this folder: pastes src/common.ps1 where a step says
// "# @@ src/common.ps1 @@", then the _shared libraries with _shared/inject.js.
// Usage: node build.js          rewrite the generated file
//        node build.js --check  exit 1 if the generated file is out of date
// Edit read.ps1, grant.ps1, note.ps1 and common.ps1 (or the libraries in _shared), never the generated .yml.
// Needs js-yaml: npm install in _shared, or set JS_YAML_PATH.
const fs = require('fs');
const path = require('path');
let y;
try { y = require('js-yaml'); } catch { try { y = require(path.join(__dirname, '..', '..', '_shared', 'node_modules', 'js-yaml')); } catch { y = require(process.env.JS_YAML_PATH); } }
const { injectText } = require(path.join(__dirname, '..', '..', '_shared', 'inject.js'));

const here = __dirname;
const root = path.join(here, '..');
const check = process.argv.includes('--check');
const read = (f) => fs.readFileSync(path.join(here, f), 'utf8').replace(/\r\n/g, '\n').trimEnd() + '\n';
const lib = (name) => `# >>> _shared/${name} (generated by _shared/inject.js; edit the source, not this block)\n# <<< _shared/${name}\n`;
const COMMON = '# @@ src/common.ps1 @@';

const preamble = (title, lines) =>
  ['# =====================================================================', `#  Mailbox / Group Access Request - ${title}`, ...lines.map((l) => `#  ${l}`),
   '#  Generated from mailbox-group-access/src. Edit the source, then run build.js.',
   '# =====================================================================', "$ErrorActionPreference = 'Stop'", 'Set-StrictMode -Version Latest', ''].join('\n') + '\n';

// A function replacement, so "$'" and "$&" in the PowerShell aren't read as replacement patterns.
const withCommon = (s) => s.replace(COMMON, () => read('common.ps1'));

const readScript = withCommon(preamble('Read the request and plan it', [
  'Read-only. Finds the user and the mailbox, group or Team, refuses privileged, role-assignable, dynamic and',
  'on-premises synced groups, checks for existing access, and works out who must approve.',
  'Secrets: M365-TenantId, M365-ClientId, M365-ClientSecret; MicrosoftExchange-* (see README).',
]) + lib('graph.ps1') + lib('exchange.ps1') + COMMON + '\n\n# ---------- this step ----------\n' + read('read.ps1'));

const grantScript = withCommon(preamble('Give the access and read it back', [
  'Changes one thing, only when confirm is true and the request is approved: a Graph group membership or',
  'ownership, or an Exchange Online mailbox permission or distribution list change. Writes nothing to the ticket.',
  'Secrets: M365-*, MicrosoftExchange-*.',
]) + lib('graph.ps1') + lib('exchange.ps1') + COMMON + '\n\n# ---------- this step ----------\n' + read('grant.ps1'));

const noteScript = preamble('Note the ticket and close it', [
  'Adds an internal note (and a public note when access was given), asks for approval by email when',
  'Access-NotifySender is set, and closes the ticket when closeTicket is true. Writes nothing when confirm is false.',
  "Secrets: PSA-Type and the PSA's own secrets; Access-NotifySender (optional, with M365-* for Mail.Send).",
]) + lib('graph.ps1') + lib('psa.ps1') + '\n# ---------- this step ----------\n' + read('note.ps1');

const testInput = {
  ticketId: '12345',
  targetUser: 'alex.kim@contoso.com',
  resource: 'sales@contoso.com',
  accessType: 'fullAccess',
  requester_email: 'alex.kim@contoso.com',
  managerEmail: '',
  approvedBy: '',
  confirm: 'false',
  closeTicket: 'true',
  company_tenant_id: '',
  psa: '',
};

const wf = {
  automationsWorkflow: 1,
  name: 'Mailbox / Group Access Request',
  description:
    'Gives a user access to an existing shared mailbox, Microsoft 365 group, security group, distribution list or Team: full access, send as, ' +
    'send on behalf, membership or ownership. Refuses privileged, role-assignable, dynamic and on-premises synced groups, and waits for the ' +
    "user's manager or the group's owner to approve. Changes nothing unless confirm is true, reads the change back, notes the PSA ticket and closes it.",
  definition: {
    schemaVersion: 1,
    activities: [
      { id: 'start', name: 'Start', type: 'start', position: { x: 80, y: 120 }, properties: { webhookEnabled: false } },
      {
        id: 'node-read', name: 'Read the request and plan it', type: 'powershell-script', position: { x: 320, y: 120 },
        properties: {
          script: readScript, timeoutSeconds: 300, retryCount: 0, parameters: [], aiExtensions: [],
          testInput: JSON.stringify(testInput, null, 2),
        },
      },
      {
        id: 'node-grant', name: 'Give the access and read it back', type: 'powershell-script', position: { x: 580, y: 120 },
        properties: {
          script: grantScript, timeoutSeconds: 300, retryCount: 0,
          parameters: [{ name: 'prep', expression: '{{ nodes.node-read.output }}' }],
          aiExtensions: [],
        },
      },
      {
        id: 'node-note', name: 'Note the ticket and close it', type: 'powershell-script', position: { x: 840, y: 120 },
        properties: {
          script: noteScript, timeoutSeconds: 300, retryCount: 0,
          parameters: [{ name: 'result', expression: '{{ nodes.node-grant.output }}' }],
          aiExtensions: [],
        },
      },
      { id: 'end', name: 'End', type: 'end', position: { x: 1080, y: 120 } },
    ],
    connections: [
      { source: 'start', target: 'node-read', sourceHandle: null },
      { source: 'node-read', target: 'node-grant', sourceHandle: null },
      { source: 'node-grant', target: 'node-note', sourceHandle: null },
      { source: 'node-note', target: 'end', sourceHandle: null },
    ],
    startActivityId: 'start',
  },
};

const header = [
  '# CloudRadial AutomationAI - Mailbox / Group Access Request (Microsoft 365, Exchange Online and the PSA ticket).',
  '# Generated by src/build.js. Edit the scripts in src/, not this file.',
  '# Import on Workflows -> Import. See README.md for secrets, permissions and inputs.',
].join('\n');
const dumped = header + '\n' + y.dump(wf, { lineWidth: -1, noRefs: true });
const { text, blocks } = injectText(dumped, 'mailbox-group-access.yml', new Map());
if (blocks.length !== 6) throw new Error(`expected 6 _shared blocks, got ${blocks.length}`);
const back = y.load(text);
JSON.parse(back.definition.activities.find((a) => a.id === 'node-read').properties.testInput);
if (back.definition.activities[0].properties.webhookEnabled !== false) throw new Error('webhook must ship off');
const need = {
  'node-read': ['function Get-GraphUser', 'function Connect-OfExchange', 'function Get-AccChange'],
  'node-grant': ['function Invoke-Graph', 'function Invoke-OfExo', 'function Test-AccHasAccess'],
  'node-note': ['function Add-PsaNote', 'function Close-PsaTicket', 'function Invoke-Graph'],
};
for (const a of back.definition.activities) {
  if (!a.properties || !a.properties.script) continue;
  for (const s of need[a.id]) if (!a.properties.script.includes(s)) throw new Error(`${a.id}: ${s} missing`);
  if (a.properties.script.includes(COMMON)) throw new Error(`${a.id}: common.ps1 marker left in`);
  if (new RegExp('[' + String.fromCharCode(0x2013, 0x2014) + ']').test(a.properties.script)) throw new Error(`${a.id}: contains an en or em dash`);
}

const p = path.join(root, 'mailbox-group-access.yml');
const was = fs.existsSync(p) ? fs.readFileSync(p, 'utf8').replace(/\r\n/g, '\n') : null;
const changed = was !== text;
console.log(`mailbox-group-access.yml: ${changed ? (check ? 'OUT OF DATE' : 'updated') : 'current'} (${text.length} bytes)`);
if (changed) {
  if (check) process.exit(1);
  fs.writeFileSync(p, text);
}
